"""Residentado Médico 2020 · Prueba B (especialidades mezcladas), preguntas 51-70"""
import lote08_base as B
L = []
HAR = "Harrison Principios de Medicina Interna 21.ª ed. (2022)"
NEL = "Nelson Tratado de Pediatría 22.ª ed. (2024)"
GUY = "Guyton y Hall Tratado de Fisiología Médica 14.ª ed. (2021)"
def Q(n, tema, cat, c, f, nota=None, **kw): B.hacer(L, "PRUEBA_B", n, tema, cat, c, f, nota, **kw)

Q(51, "Síndrome urémico hemolítico", "Nefrología pediátrica",
  "El síndrome urémico hemolítico típico es la causa más frecuente de insuficiencia renal aguda en lactantes y preescolares. Aparece pocos días después de una diarrea con sangre causada por Escherichia coli productora de toxina Shiga (O157:H7 y otros serotipos), cuya toxina daña el endotelio de la microvasculatura renal y produce microangiopatía trombótica. La tríada clásica es anemia hemolítica microangiopática, trombocitopenia e insuficiencia renal aguda con daño endotelial. El niño del caso reúne el antecedente de diarrea con moco y sangre, palidez, edema palpebral, oliguria pese a mejorar las deposiciones y valores de hemoglobina baja y creatinina elevada para la edad. La deshidratación no explica la anuria cuando ya recibió líquidos y las diarreas disminuyen; la sepsis de foco enteral y la enterocolitis complicada no producen por sí solas anemia hemolítica con falla renal; la infección urinaria no se asocia con este cuadro. Para confirmar se piden frotis (esquistocitos), plaquetas, LDH, haptoglobina y búsqueda de toxina Shiga en heces. El tratamiento es de soporte: control cuidadoso de líquidos y electrolitos, transfusión si es necesaria y diálisis cuando hay indicación; se evitan antimotilidad y, por lo general, los antibióticos. Las revisiones de 2024 (Gülhan) destacan el diagnóstico diferencial con el síndrome urémico hemolítico atípico, mediado por el complemento, que sí puede requerir eculizumab. Perla: ante diarrea sanguinolenta con oliguria y palidez, pide hemograma, plaquetas y creatinina.",
  "Gülhan B. Turk J Pediatr 2024;66:1-16 (manejo del síndrome urémico hemolítico pediátrico; solo resumen); Wildes DM et al. Pediatr Nephrol 2024;39:315-24 (eculizumab en STEC-HUS con compromiso neurológico; solo título y resumen); " + NEL,
  a="nefrologia")

Q(52, "Enfermedad de Whipple", "Gastroenterología",
  "La enfermedad de Whipple es una infección sistémica crónica por Tropheryma whipplei, un actinomiceto que invade la lámina propia del intestino delgado y otros órganos. Afecta sobre todo a varones de mediana edad, pero puede ocurrir en mujeres, y se manifiesta con diarrea crónica, esteatorrea, pérdida de peso, artralgias migratorias que pueden preceder al cuadro intestinal durante años, y a veces fiebre, adenopatías o compromiso neurológico y cardiaco. La esteatorrea de 12 g al día con prueba de D-xilosa sin alteración, aunque suele esperarse algo de malabsorción, y sobre todo la biopsia duodenal con macrófagos llenos de gránulos PAS positivos en la lámina propia, sostienen el diagnóstico, que se confirma con reacción en cadena de la polimerasa. El sobrecrecimiento bacteriano no muestra macrófagos PAS positivos; la infección por Mycobacterium avium en pacientes con VIH produce macrófagos PAS positivos pero con bacilos ácido alcohol resistentes; Cryptosporidium se identifica en heces y no origina ese infiltrado; la hipogammaglobulinemia cursa con ausencia de células plasmáticas. El tratamiento es antibiótico prolongado, con una fase inicial parenteral y otra de mantenimiento durante meses a un año o más, con vigilancia del síndrome inflamatorio de reconstitución inmune. Los autores de revisiones recientes (Cappellini 2024; Viegas 2023) destacan que el diagnóstico se retrasa porque el cuadro es raro y comienza con síntomas articulares. Perla: ante artralgias crónicas seguidas de diarrea y adelgazamiento, piensa en Whipple antes de iniciar inmunosupresores.",
  "Cappellini A et al. Eur J Intern Med 2024;121:25-9 (enfermedad de Whipple; solo resumen); Viegas AF et al. Cureus 2023;15:e34029 (diagnóstico difícil de la enfermedad de Whipple); Song X et al. Front Immunol 2023;14:1265414 (síndrome inflamatorio de reconstitución inmune en Whipple); " + HAR,
  a="gastroenterologia")

Q(53, "Anticoncepción en fumadora con diabetes tipo 1", "Planificación familiar",
  "Para elegir un método anticonceptivo se aplican los criterios médicos de elegibilidad, que asignan una categoría de 1 a 4 según el riesgo de cada método frente a la condición de la paciente. En una mujer de 30 años que fuma 20 cigarrillos diarios y tiene diabetes tipo 1 de 21 años de evolución, los estrógenos aumentan el riesgo trombótico y cardiovascular, que ya está elevado por el tabaquismo intenso y por la larga duración de la diabetes, la cual puede dañar los vasos. Los criterios estadounidenses de 2024 consideran que una persona fumadora menor de 35 años puede usar píldora combinada con categoría 2, pero la suma de tabaquismo intenso y diabetes prolongada hace desaconsejable la píldora combinada. El dispositivo intrauterino de cobre carece de efecto hormonal y metabólico, no modifica el control glucémico y no se asocia con riesgo vascular, por lo que es el método más seguro en este caso y la clave oficial. El progestágeno inyectable puede alterar el metabolismo de la glucosa y el perfil lipídico; la píldora de solo progestágeno y el dispositivo con levonorgestrel son alternativas razonables, pero tienen menos ventaja que el cobre en esta paciente nuligesta que no tiene alteraciones menstruales. Perla: en diabetes con tabaquismo, evita estrógenos y prefiere métodos sin efecto metabólico, además de insistir en dejar de fumar.",
  "Nguyen AT et al. MMWR Recomm Rep 2024;73(4):1-126 (U.S. Medical Eligibility Criteria for Contraceptive Use, 2024; texto parcial leído en PMC); Curtis KM et al. Contraception 2026;159:111015 (uso de los criterios 2024 en la decisión anticonceptiva); " + "Williams Obstetricia 26.ª ed. (2022)",
  nota="El dispositivo con levonorgestrel también es una opción segura según los criterios vigentes; la clave oficial elige el de cobre por no tener efecto hormonal.",
  a="ginecologia")

Q(54, "Eficiencia en programas de salud", "Gestión en salud",
  "En la evaluación de programas de salud se distinguen conceptos que se confunden con facilidad. La eficacia es el grado en que una intervención logra el resultado esperado en condiciones ideales o controladas; la efectividad es ese mismo logro en condiciones reales de práctica; la eficiencia relaciona los resultados obtenidos con los recursos empleados, es decir, el logro de los objetivos al menor costo posible o la mejor producción con los insumos disponibles. Por eso la definición correcta es lograr los objetivos con el menor costo. Cuando solo se menciona el costo del programa se describe un insumo y no una relación; la satisfacción del usuario es un indicador de calidad percibida; el logro sostenible de resultados corresponde a la sostenibilidad, y alcanzar los objetivos sin considerar los recursos define la eficacia o la efectividad, según el contexto. Además, la equidad y la cobertura son criterios independientes. En la práctica la eficiencia se analiza con evaluaciones económicas (costo-efectividad, costo-utilidad, costo-beneficio) y, en sistemas de salud, con modelos que comparan insumos como gasto, personal y camas con productos como esperanza de vida y mortalidad infantil. Una revisión de 2024 evaluó la eficiencia de 28 sistemas de salud precisamente con esa lógica de insumos y resultados. Perla: eficacia es lograr el objetivo, efectividad es lograrlo en la práctica y eficiencia es lograrlo gastando menos.",
  "Dlouhý M et al. Health Econ Rev 2024;14:59 (evaluación de la eficiencia de 28 sistemas de salud por MCDA y DEA)",
  a="salud_publica")

Q(55, "Náuseas y vómitos del embarazo leves", "Obstetricia",
  "Las náuseas y vómitos del embarazo afectan a la mayoría de gestantes en el primer trimestre y alcanzan su pico entre las 8 y 12 semanas, en relación con la gonadotropina coriónica y los estrógenos. Se gradúan con herramientas validadas como el índice PUQE, y se distinguen de la hiperémesis gravídica por la pérdida de más del 5 % del peso, la deshidratación y los trastornos electrolíticos. La paciente tiene síntomas leves, sin pérdida de peso, signos vitales normales y sin deshidratación; por eso corresponde empezar con medidas dietéticas (comidas pequeñas y frecuentes, evitar olores desencadenantes) y piridoxina, que es la opción inicial en cuadros leves. Si no cede se añade un antihistamínico como doxilamina, y la combinación doxilamina-piridoxina es una opción de primera línea. La guía británica de 2024 señala que los antihistamínicos H1, las fenotiazinas y la doxilamina-piridoxina son los antieméticos de primera línea, que la metoclopramida es segura y eficaz en combinación, y que la ondansetrón se reserva como segunda línea. Esa guía también precisa que la cetonuria no indica deshidratación y no debe usarse para valorar la gravedad. La domperidona, el omeprazol y la prometazina no son el tratamiento inicial de un cuadro leve. Perla: si hay pérdida de peso o cetonuria con intolerancia oral, se hospitaliza para hidratación y antieméticos parenterales.",
  "Nelson-Piercy C et al. BJOG 2024;131:e1-e30 (Green-top Guideline N.º 69; leído el resumen con las recomendaciones); Kothari S et al. Gastroenterology 2024;167:1033-45 (AGA, actualización sobre enfermedad digestiva y hepática del embarazo; solo resumen); Williams Obstetricia 26.ª ed. (2022)",
  nota="La guía británica de 2024 coloca antihistamínicos, fenotiazinas y doxilamina-piridoxina como primera línea; la piridoxina sola es la medida inicial en cuadros leves, como indica la clave oficial.",
  a="ginecologia")

Q(56, "Herpes zoster recurrente", "Infectología",
  "El herpes zoster resulta de la reactivación del virus varicela-zóster latente en los ganglios sensitivos, cuando disminuye la inmunidad celular específica. Aparece con una erupción vesicular dolorosa en un dermatoma. En personas inmunocompetentes la recurrencia es poco frecuente, de modo que un cuarto episodio en una persona de 43 años, confirmado por cultivo, obliga a buscar una inmunodeficiencia de base. La causa más frecuente de zoster recurrente o multidermatómico en adultos jóvenes es la infección por VIH, en la que la reactivación puede ocurrir años antes del diagnóstico de sida y aparece incluso con recuento de linfocitos CD4 relativamente conservado. El tratamiento crónico con prednisona, la leucemia, el linfoma y la diabetes aumentan el riesgo de zoster, pero causan con menos frecuencia episodios repetidos tan seriados. Se debe ofrecer prueba de VIH a todo adulto con zoster recurrente, y la norma peruana de 2020 establece el tamizaje en grupos de riesgo y la atención integral. Una revisión de 2024 (Lim) resume el diagnóstico, tratamiento antiviral con aciclovir, valaciclovir o famciclovir iniciado en las primeras 72 horas y estrategias de vacunación, y un estudio de 2025 (Arsuffi) analiza la reactivación en personas con VIH vacunadas con vacuna recombinante. Perla: zoster en un adulto joven o con varios episodios es motivo para solicitar prueba de VIH.",
  "Lim DZJ et al. Pathogens 2024;13(7):1-17 (herpes zóster y neuralgia posherpética; texto en PMC11280284); Arsuffi S et al. Vaccine 2025;64:127723 (reactivación de herpes zóster en personas con VIH vacunadas con vacuna recombinante; solo resumen); NTS 169-MINSA/2020/DGIESP (atención integral del adulto con VIH); " + HAR,
  a="infectologia")

Q(57, "Diagnóstico de asma en el niño", "Neumología pediátrica",
  "El asma es una enfermedad inflamatoria crónica de la vía aérea con obstrucción variable y reversible. En el preescolar y escolar se sospecha por sibilancias recurrentes, tos y dificultad respiratoria que empeoran con infecciones virales, ejercicio o alérgenos, y por antecedentes de atopía: rinitis alérgica, dermatitis atópica y síndrome obstructivo bronquial a repetición. El niño del caso tiene los tres antecedentes, y ahora una crisis con taquipnea, tirajes y sibilancias, lo que indica exacerbación asmática. La bronquiolitis es propia del lactante menor de dos años en su primer episodio; el reflujo gastroesofágico puede causar tos y sibilancias pero sin atopía; la bronquitis aguda no cursa con tirajes ni obstrucción marcada; el cuerpo extraño debe sospecharse ante inicio súbito con atragantamiento y hallazgos focales. Los estertores gruesos acompañantes se atribuyen a secreciones. El manejo de la exacerbación incluye oxígeno si hay hipoxemia, agonistas beta-2 de acción corta inhalados repetidos, bromuro de ipratropio en crisis moderadas a graves y corticoide sistémico precoz. El informe de la Iniciativa Global para el Asma de 2024 diferencia el manejo de niños de 5 años o menos y de 6 a 11 años, y recomienda que los escolares no reciban tratamiento solo con aliviadores, sino con corticoide inhalado. Perla: en el niño atópico con sibilancias recurrentes, piensa primero en asma.",
  "Global Initiative for Asthma. Global Strategy for Asthma Management and Prevention, 2024 update (informe 2024 y guía resumida 2024; consultados en el sitio oficial); Craig S et al. Arch Dis Child 2024;109:468-75 (análisis de recomendaciones de guías para exacerbaciones de asma en niños; solo resumen); " + NEL,
  a="neumologia")

Q(58, "Hernia diafragmática congénita", "Neonatología",
  "La hernia diafragmática congénita es un defecto del diafragma, casi siempre posterolateral izquierdo (hernia de Bochdalek), por el cual las vísceras abdominales pasan al tórax durante la vida fetal y comprimen el pulmón en desarrollo. El resultado es hipoplasia pulmonar e hipertensión pulmonar persistente, que determinan la morbilidad y la mortalidad. El recién nacido a término presenta dificultad respiratoria y cianosis desde los primeros minutos, abdomen excavado o escafoides (porque las asas están en el tórax), tórax asimétrico, desplazamiento de los ruidos cardiacos y ruidos hidroaéreos en el hemitórax afectado. La radiografía muestra asas con gas en el tórax y desvío del mediastino. La enterocolitis necrosante es propia del prematuro y aparece días después con distensión; la agenesia pulmonar es muy rara y no se acompaña de un abdomen vacío; el síndrome de aspiración de meconio cursa con tórax hiperinsuflado y antecedente de líquido meconial, y la enfermedad de membranas hialinas afecta a prematuros con abdomen no excavado. En la sala de partos se evita la ventilación con mascarilla, que insufla el estómago y el intestino, se intuba y se coloca una sonda orogástrica de descompresión; la cirugía se difiere hasta estabilizar al recién nacido. Una revisión de 2024 (Baschat) integra el manejo prenatal, con terapia fetal en casos graves, y el posnatal. Perla: abdomen excavado más dificultad respiratoria inmediata es hernia diafragmática hasta demostrar lo contrario.",
  "Baschat AA et al. Transl Pediatr 2024;13:643-62 (avances en el manejo de la hernia diafragmática congénita, prenatal y posnatal; texto en PMC11071032, leído el resumen); Holden KI et al. Semin Pediatr Surg 2024;33:151437 (hipertensión pulmonar asociada a hernia diafragmática congénita; solo título); " + NEL,
  a="pediatria")

Q(59, "Bronquiolitis", "Neumología pediátrica",
  "La bronquiolitis es la primera infección viral del tracto respiratorio inferior en el lactante, causada sobre todo por virus sincitial respiratorio. Cursa con un pródromo catarral de rinorrea y fiebre, seguido a los dos o tres días de tos, taquipnea, tirajes, sibilancias y subcrepitantes bilaterales, con rechazo de las tomas y saturación baja. El lactante de dos meses del caso presenta ese curso típico y signos de gravedad (saturación de 90 %, dificultad para alimentarse). La bronquitis aguda es infrecuente a esa edad; la crisis asmática exige episodios previos y atopía; la tos ferina cursa con tos en accesos y apneas con escasa fiebre; la neumonía bacteriana muestra fiebre alta y condensación focal. El diagnóstico es clínico y no requiere radiografía de rutina. El tratamiento es de soporte: oxígeno, hidratación o alimentación asistida y aspiración nasal. La guía australiana de 2025 recomienda no emplear agonistas beta-2, adrenalina ni glucocorticoides de rutina; sugiere considerar oxígeno si la saturación se mantiene por debajo de 90 % en lactantes de 6 semanas o más (92 % si son menores o tienen enfermedad de base), y reservar la cánula nasal de alto flujo para lactantes hipoxémicos que fracasan con oxígeno de bajo flujo. También considera los anticuerpos monoclonales como el nirsevimab para prevención. Perla: en la bronquiolitis, lo que más ayuda es oxigenar, hidratar y despejar la nariz.",
  "Borland ML et al. J Paediatr Child Health 2025;61:1197-215 (Australasian Bronchiolitis Guideline, actualización 2025; texto completo leído en PMC12397848); Radcliffe CR et al. J Pediatr Health Care 2025;39:638-45 (aplicación práctica de las recomendaciones de nirsevimab; solo título); " + NEL,
  nota="La guía australiana define bronquiolitis en menores de 12 meses; el lactante de dos meses del caso cumple esa definición.",
  a="pediatria")

Q(60, "Placa motora: canales de calcio", "Fisiología",
  "En la unión neuromuscular, el potencial de acción del motoneurona alcanza la terminal presináptica y despolariza su membrana. Esa despolarización abre canales de calcio dependientes de voltaje (tipo P/Q en la placa terminal de mamíferos), y el calcio que entra a favor de su gradiente hace que las vesículas con acetilcolina se fusionen con la membrana y liberen el neurotransmisor por exocitosis. La acetilcolina difunde por la hendidura sináptica y se une a los receptores nicotínicos de la membrana postsináptica, canales catiónicos que dejan entrar sodio y producen el potencial de placa terminal, que desencadena el potencial de acción muscular. La acetilcolinesterasa degrada rápidamente el transmisor. Por eso la respuesta correcta es calcio: el sodio entra sobre todo en la célula muscular tras la unión del transmisor; el potasio participa en la repolarización; el cloro estabiliza el potencial en reposo del músculo, y el fósforo no es un ion de conducción. La clínica ilustra el mecanismo: en el síndrome miasténico de Lambert-Eaton los anticuerpos contra los canales de calcio presinápticos reducen la liberación de acetilcolina, y en la miastenia gravis los anticuerpos atacan los receptores postsinápticos. La toxina botulínica impide la liberación del transmisor. Una revisión de 2023 (Kouyoumdjian) sobre la evaluación electrofisiológica de la unión neuromuscular repasa estas bases. Perla: el calcio presináptico es el paso que acopla el potencial de acción a la liberación de acetilcolina.",
  "Kouyoumdjian JA et al. Arq Neuropsiquiatr 2023;81:1040-52 (evaluación electrofisiológica de la unión neuromuscular: revisión breve; PMC10756823); " + GUY,
  a="ciencias_basicas")

Q(61, "Diagnóstico nutricional por IMC en el niño", "Pediatría",
  "En niños de 5 a 19 años el estado nutricional se clasifica con el índice de masa corporal para la edad y el sexo, comparado con las curvas de referencia, y no con los valores absolutos del adulto. La referencia de la Organización Mundial de la Salud de 2007 usa desviaciones estándar: sobrepeso a más de +1 y obesidad a más de +2, un valor próximo al percentil 97 a 98. Un niño de 6 años con IMC de 20 situado en el percentil 98 supera ese punto de corte, de modo que el diagnóstico es obesidad. La guía de la Academia Americana de Pediatría de 2023 sobre evaluación y tratamiento de la obesidad infantil también utiliza el IMC por percentiles. El eutrófico se ubica entre percentiles aproximados de 15 y 85 (o ±1 desviación estándar); el sobrepeso, entre el percentil 85 y el 97; el bajo peso queda por debajo del percentil 3 (menos de -2 desviaciones estándar), y la desnutrición severa se define con puntajes aún más bajos. La obesidad infantil se asocia con resistencia a la insulina, hígado graso, hipertensión, apnea del sueño y obesidad en la vida adulta. El manejo combina intervención conductual y familiar, alimentación saludable y actividad física, con evaluación de comorbilidades. Perla: un IMC de 20 es normal en un adulto, pero en un niño de 6 años por encima del percentil 97 indica obesidad.",
  "Hampl SE et al. Pediatrics 2023;151(2):e2022060640 (guía de práctica clínica de la AAP sobre evaluación y tratamiento de la obesidad en niños y adolescentes; solo título consultado); de Onis M et al. Bull World Health Organ 2007;85:660-7 (referencia OMS 2007, texto completo en PMC2636412); " + NEL,
  a="pediatria")

Q(62, "Hito motor: sedestación sin apoyo", "Pediatría",
  "El desarrollo motor grueso sigue una secuencia cefalocaudal y proximal a distal. Hacia los 2 a 3 meses el lactante sostiene la cabeza en prono; a los 4 a 5 meses se voltea y se sienta con apoyo; a los 6 a 7 meses logra la sedestación estable sin sostén, apoyándose primero en las manos y luego libre; hacia los 9 meses gatea y se pone de pie con apoyo; y alrededor del año camina con ayuda o solo. Por eso el lactante que permanece sentado sobre una superficie firme sin apoyo ni sujeción corresponde a unos 7 meses de edad. A los 2 a 3 meses solo hay control cefálico incompleto; a los 4 a 5 meses aún precisa apoyo del tronco. El estudio multicéntrico de la Organización Mundial de la Salud sobre desarrollo motor (2006) definió ventanas de logro amplias para la sedestación sin ayuda, de modo que variaciones de pocos meses son normales. La revisión de los hitos del Centro para el Control de Enfermedades (CDC) de 2022 adoptó el criterio de que los hitos listados son los que logra el 75 % o más de los niños de esa edad, lo cual los desplaza a edades algo más tardías que las de los textos clásicos. Un retraso notable en la sedestación sin apoyo después del noveno mes obliga a evaluar hipotonía, enfermedad neuromuscular o déficit del desarrollo. Perla: el hito se evalúa como ventana de edad, no como un día exacto.",
  NEL + "; Zubler JM et al. Pediatrics 2022;149(3):e2021052138 (hitos del desarrollo basados en evidencia, texto completo en PMC9680195; base de los hitos revisados del CDC); WHO Multicentre Growth Reference Study Group. Acta Paediatr Suppl 2006;450:86-95 (ventanas de logro de seis hitos motores)",
  nota="Según la clave oficial el hito corresponde a 7 meses; las listas de hitos del CDC revisadas en 2022 (75 % de los niños) sitúan la sedestación sin apoyo en edades algo posteriores, por lo que la edad se toma como ventana, no como valor exacto.",
  a="pediatria")

Q(63, "Apendicitis aguda en el anciano: estudio de imagen", "Cirugía",
  "En el adulto mayor la apendicitis aguda se presenta de forma atípica: dolor mal localizado, anorexia, malestar general o dificultad para caminar, poca fiebre y leucocitosis discreta, y llega tarde a la consulta, con mayor riesgo de perforación y de mortalidad. El hombre de 76 años tiene dolor hipogástrico, peritonismo con Blumberg positivo, McBurney dudoso, taquipnea y líquido libre en la pelvis en la ecografía, lo cual sugiere una complicación como perforación, pero la causa no se aclara: podrían ser apendicitis perforada, diverticulitis complicada, neoplasia o isquemia. La tomografía computarizada con contraste es el estudio de elección porque define la causa y la extensión, orienta entre cirugía y drenaje y descarta otros diagnósticos. Un estudio multicéntrico europeo de 2024 mostró que los ancianos con apendicitis consultaron más tarde (7,9 frente a 3,6 días) y necesitaron tomografía con mucha más frecuencia (86 % frente a 54 %). Repetir el hemograma o la ecografía retrasa la decisión; la colonoscopia es riesgosa en un abdomen agudo con peritonismo y el enema baritado está contraindicado ante sospecha de perforación. La edición 2025 de las guías de Jerusalén de la sociedad mundial de cirugía de urgencia mantiene el abordaje diagnóstico basado en puntuaciones clínicas y en imagen según el contexto. La guía de apendicitis aguda de EsSalud-IETSI (2022) también orienta el diagnóstico. Perla: en el anciano con abdomen agudo, no esperes: tomografía contrastada.",
  "Cimino MM et al. Eur J Trauma Emerg Surg 2024;50:2155-64 (apendicitis en el anciano, estudio ESTES SnapAppy; resumen y texto en PMC11599287); Podda M et al. JAMA Surg 2026;161:283-95 (WSES Jerusalem, edición 2025; solo resumen); GPC de apendicitis aguda EsSalud-IETSI (2022); Sabiston Tratado de Cirugía 22.ª ed. (Elsevier, 2025)",
  a="cirugia")

Q(64, "Meningitis meningocócica: corticoide y antibiótico", "Infectología",
  "La meningitis bacteriana aguda se manifiesta con cefalea, fiebre, rigidez de nuca y alteración del sensorio, y es una urgencia médica. En una joven de 18 años, los cocos gramnegativos (diplococos) en el líquido cefalorraquídeo indican Neisseria meningitidis, que puede asociarse con petequias o púrpura y sepsis. El punto central del tratamiento es no retrasar el antibiótico: ceftriaxona o cefotaxima iniciadas de inmediato. La clave oficial prioriza la corticoterapia seguida de antibióticos, de acuerdo con la práctica clásica de administrar dexametasona antes o junto con la primera dosis antibiótica para reducir la respuesta inflamatoria liberada con la lisis bacteriana, que causa secuelas auditivas y neurológicas. Las demás opciones fallan: cubrir solo gramnegativos de forma empírica es erróneo porque el agente es meningococo y se pueden requerir esquemas amplios hasta tener cultivo; el manitol no es tratamiento de rutina; los corticoides sin antibiótico o con espera del cultivo son peligrosos. Una revisión de 2023 (Pajor) indica que el tratamiento empírico del adulto consiste en vancomicina, ceftriaxona y dexametasona. La nueva guía alemana (Hadjilaou 2024) precisa los ámbitos y la duración de la dexametasona, sobre todo en la meningitis neumocócica, donde los datos son controvertidos para otros agentes. Los contactos cercanos reciben quimioprofilaxis. Perla: nunca retrases el antibiótico por esperar el corticoide o una prueba de imagen.",
  "Pajor MJ et al. Am J Emerg Med 2023;65:76-83 (meningitis bacteriana del adulto; solo resumen); Hadjilaou A et al. Dtsch Med Wochenschr 2024;149:1021-7 (nueva guía alemana de meningoencefalitis bacteriana adquirida en la comunidad; solo resumen); Marshall HS et al. Eur J Clin Microbiol Infect Dis 2025;44:233-50 (manejo y prevención de infecciones por Neisseria meningitidis y gonorrhoeae; solo título); " + HAR,
  nota="Las guías vigentes recomiendan dexametasona antes o junto con la primera dosis de antibiótico, sin retrasarlo; el beneficio es más sólido en meningitis neumocócica y es discutido en la meningocócica. La clave oficial se mantiene.",
  a="infectologia")

Q(65, "SERVQUAL: dimensión de empatía", "Calidad en salud",
  "El modelo SERVQUAL mide la calidad percibida comparando las expectativas del usuario con su percepción del servicio recibido, a través de cinco dimensiones. La fiabilidad es la capacidad de cumplir lo prometido de forma confiable y exacta; la capacidad de respuesta es la disposición para ayudar y atender con prontitud; la seguridad abarca el conocimiento, la cortesía y la capacidad del personal para inspirar confianza; los elementos tangibles son las instalaciones, los equipos, el personal y los materiales de comunicación; y la empatía consiste en brindar atención individualizada, con interés genuino por comunicarse y comprender las necesidades del paciente. El enunciado describe justamente esta última, que se evidencia en el trato personalizado, la escucha activa y la información clara. En el Perú el Ministerio de Salud aprobó en 2011, mediante la RM 527-2011/MINSA, una guía técnica para evaluar la satisfacción del usuario externo en los establecimientos de salud, que utiliza una versión modificada del instrumento, y que se sigue citando en documentos recientes. La satisfacción se obtiene de la diferencia entre percepciones y expectativas: una brecha negativa indica insatisfacción. Revisiones recientes (Alizadeh 2025; Rahmatia 2025) describen la aplicación de SERVQUAL en hospitales y la identificación de brechas por dimensión. Perla: atención individualizada y comprensión de las necesidades del paciente equivale a empatía.",
  "Resolución Ministerial 527-2011/MINSA (11 de julio de 2011), Guía técnica para la evaluación de la satisfacción del usuario externo en los establecimientos de salud y servicios médicos de apoyo (número y fecha confirmados por búsqueda web; texto no abierto); Alizadeh T et al. Health Sci Rep 2025;8:e70362 (calidad del servicio en hospitales iraníes con SERVQUAL: revisión sistemática; PMC11752147); Rahmatia S et al. Health SA 2025;30:3055 (calidad del servicio en hospitalización con SERVQUAL)",
  a="salud_publica")

Q(66, "Reflujo vesicoureteral grado II", "Urología pediátrica",
  "El reflujo vesicoureteral es el paso retrógrado de orina de la vejiga al uréter y se gradúa de I a V con la clasificación internacional por cistouretrografía miccional. En el grado II el contraste llega a la pelvis y los cálices sin dilatarlos, y la morfología papilar es normal. Los grados I a III de bajo grado tienen una alta tasa de resolución espontánea, que ocurre al madurar la unión ureterovesical y crecer el túbulo intramural del uréter, sobre todo en niños pequeños, por lo que la conducta inicial es la observación o vigilancia, con seguimiento clínico, control de las infecciones urinarias y manejo de la disfunción vesical e intestinal. La actualización de 2023 de las guías de la Asociación Europea de Urología y la Sociedad Europea de Urología Pediátrica propone un abordaje basado en riesgo, con diagnóstico selectivo, y señala que la profilaxis antibiótica continua puede no ser necesaria en todos los pacientes. Una revisión de 2024 (Puri) enumera las opciones: vigilancia o tratamiento intermitente de infecciones, profilaxis continua, inyección endoscópica y reimplante ureteral abierto, laparoscópico o robótico. La cirugía o la inyección endoscópica se reservan para reflujo de alto grado, infecciones febriles recurrentes a pesar de profilaxis, cicatrices renales nuevas o falta de resolución. Perla: el reflujo de bajo grado en una niña pequeña sin infecciones recurrentes se vigila, no se opera.",
  "Gnech M et al. Eur Urol 2024;85:433-42 (actualización 2023 del capítulo de reflujo vesicoureteral de las guías EAU/ESPU; resumen leído); Puri P et al. Nat Rev Dis Primers 2024;10:75 (reflujo vesicoureteral primario; resumen leído); Hari P et al. Pediatr Nephrol 2024;39:1639-68 (guía de la Sociedad India de Nefrología Pediátrica sobre infección urinaria y reflujo; solo resumen); " + NEL,
  a="nefrologia")

Q(67, "Campylobacter jejuni", "Infectología pediátrica",
  "Campylobacter jejuni es una de las causas más frecuentes de diarrea bacteriana en el mundo. Se transmite por alimentos contaminados, sobre todo carne de ave cruda o poco cocida, agua no tratada y contacto con animales de granja y domésticos; la incidencia es máxima en menores de 5 años. Tras incubar de 2 a 5 días produce fiebre, dolor abdominal cólico, náuseas y diarrea acuosa que evoluciona a disentería con moco y sangre. Puede localizarse en el íleon terminal y el ciego y simular una apendicitis (seudoapendicitis), como en este niño con dolor en fosa ilíaca derecha sin defensa, razón por la que el cirujano pediatra debe descartar un abdomen quirúrgico. El contacto con aves de corral orienta a Campylobacter; Vibrio cholerae causa diarrea acuosa profusa en «agua de arroz»; Giardia produce diarrea crónica con esteatorrea sin sangre; Shigella flexneri también da disentería, pero se vincula más con transmisión fecal-oral y hacinamiento; el rotavirus causa diarrea acuosa con vómitos sin sangre. Es autolimitado, y el tratamiento principal es la rehidratación. Una revisión de 2024 (Veronese) señala que las guías internacionales coinciden en recomendar antibióticos en infecciones intestinales graves o en huéspedes de riesgo, y menciona como complicaciones tardías la artritis reactiva y el síndrome de Guillain-Barré. Perla: diarrea con sangre más contacto con aves de corral es Campylobacter hasta demostrar lo contrario.",
  "Veronese P et al. Microorganisms 2024;12(12):2573-90 (infección por Campylobacter jejuni/coli: ¿sigue siendo una preocupación?; PMC11728820, resumen leído); Cohen R et al. Infect Dis Now 2023;53(8S):104784 (tratamiento antiinfeccioso de las infecciones gastrointestinales en niños; solo título); " + NEL,
  a="infectologia")

Q(68, "Mieloma múltiple y síndrome de Fanconi", "Nefrología",
  "En el mieloma múltiple las cadenas ligeras monoclonales libres se filtran en el glomérulo y se reabsorben en el túbulo proximal, donde pueden acumularse y dañar las células. Cuando son tóxicas, producen la tubulopatía proximal por cadenas ligeras, que puede cursar como síndrome de Fanconi adquirido. El túbulo contorneado proximal reabsorbe normalmente la glucosa, los aminoácidos, el fosfato, el ácido úrico y el bicarbonato; su lesión causa glucosuria con glucemia normal, aminoaciduria, hipofosfatemia, uricosuria y acidosis tubular proximal (tipo 2) hiperclorémica con pérdida de bicarbonato, exactamente el cuadro descrito. El túbulo distal y los conductos colectores regulan la acidificación y la concentración de la orina; la rama gruesa ascendente reabsorbe sodio, potasio y cloro con el cotransportador NKCC2, y los capilares glomerulares se afectan en depósitos como la amiloidosis o la podocitopatía por cristales. La otra lesión clásica del mieloma es la nefropatía por cilindros, que obstruye los túbulos distales con cilindros de cadenas ligeras y la proteína de Tamm-Horsfall, con insuficiencia renal aguda. Una serie de 2023 (Kousios) describe la tubulopatía proximal por cadenas ligeras no cristalina y su relación con mieloma o gammapatía monoclonal de significado renal, con clon detectado en todos los casos. El tratamiento se dirige al clon plasmocitario. Perla: Fanconi más proteína monoclonal es tubulopatía proximal por cadenas ligeras.",
  "Kousios A et al. Nephrol Dial Transplant 2023;38:2576-88 (tubulopatía proximal por cadenas ligeras no cristalina; texto en PMC10615624, resumen leído); Nasr SH et al. Kidney Int 2023;103:616-26 (podocitopatía cristalina por cadenas ligeras; solo título); " + HAR,
  a="nefrologia")

Q(69, "Regulación del vaciamiento gástrico", "Fisiología digestiva",
  "El vaciamiento gástrico está regulado por reflejos nerviosos y señales hormonales que se originan en el duodeno, el cual limita la velocidad con que le llega el quimo para no exceder su capacidad de digerir y absorber. Los estímulos duodenales que retrasan el vaciamiento son la distensión, la irritación de la mucosa, la acidez del quimo, la hiperosmolaridad y la presencia de productos de la digestión de grasas y proteínas. La grasa es el estímulo más potente: los ácidos grasos libres inducen la liberación de colecistocinina, que inhibe la motilidad antral, aumenta el tono del píloro y relaja el estómago proximal, y de otras señales que actúan como freno, entre ellas el péptido inhibidor gástrico y el péptido YY. Por eso las comidas ricas en grasa permanecen más tiempo en el estómago. El pH alto del quimo no frena el vaciamiento: lo hace el pH ácido, que activa la secretina y reflejos enterogástricos; el almidón y la solución isotónica de cloruro de sodio casi no lo retrasan, y la proteína tiene un efecto menor que la grasa. Estos mecanismos explican la saciedad prolongada tras comer grasa y la utilidad terapéutica de ralentizar el vaciamiento con agonistas del péptido similar al glucagón tipo 1. Una revisión de 2023 sobre gastroparesia (Ramos) recoge las controversias actuales de la evaluación del vaciamiento gástrico. Perla: grasa en duodeno, colecistocinina y vaciamiento más lento.",
  GUY + "; Ramos GP, Camilleri M et al. Neurogastroenterol Motil 2023;35:e14494 (diez controversias en gastroparesia; PMC10133001, solo resumen); Camilleri M. Curr Opin Endocrinol Diabetes Obes 2019;26:3-10 (hormonas gastrointestinales y regulación del vaciamiento gástrico, PMC6615897)",
  nota="La referencia de 2019 de Camilleri se cita como respaldo de la fisiología; la fuente del periodo 2023-2026 es la revisión de gastroparesia de 2023.",
  a="ciencias_basicas")

Q(70, "Fuerzas de Starling: filtración capilar", "Fisiología cardiovascular",
  "El intercambio de líquido a través de la pared capilar sigue el principio de Starling: la filtración neta depende del coeficiente de filtración y de la diferencia entre las presiones hidrostáticas y oncóticas que actúan a ambos lados. Las fuerzas que favorecen la filtración hacia el intersticio son la presión hidrostática capilar y la presión oncótica intersticial; las que se oponen son la presión oncótica del plasma, que retiene agua en el capilar, y la presión hidrostática intersticial. El aumento de la presión hidrostática capilar, por ejemplo en la insuficiencia cardiaca, la hipervolemia o la obstrucción venosa, empuja más líquido al intersticio y es la respuesta correcta. Una disminución del coeficiente de filtración reduce la filtración, y un aumento de ese coeficiente (como ocurre en la inflamación) la incrementa; la caída de la presión oncótica intersticial disminuye el gradiente favorable; el aumento de la presión hidrostática intersticial se opone a la filtración, y el aumento de la presión oncótica capilar (hemoconcentración) retiene líquido en el vaso. La clínica lo confirma: el edema aparece por mayor presión capilar, menor albúmina plasmática (síndrome nefrótico, cirrosis) o aumento de la permeabilidad. El principio revisado de Starling incorpora el glucocáliz endotelial y el flujo linfático, y en la revisión de 2023 (Alamilla-Sanchez) se discute su aplicación a la prescripción racional de líquidos. Perla: más presión hidrostática capilar, más edema.",
  "Alamilla-Sanchez ME et al. Int J Gen Med 2023;16:2753-70 (avances en la fisiología del intercambio transvascular y prescripción racional de líquidos; texto en PMC10319290, solo resumen); Levick JR, Michel CC. Cardiovasc Res 2010;87:198-210 (principio de Starling revisado); " + GUY,
  a="ciencias_basicas")
